import { Link, useNavigate } from "react-router-dom";
import { useState, useRef, useEffect } from "react";

function Navbar({ userRole }) {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false); // Mobile menu toggle
  const [dropdownOpen, setDropdownOpen] = useState(null); // Track which dropdown is open
  const menuRef = useRef(); // Ref for the whole menu

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const toggleDropdown = (menu) => {
    setDropdownOpen(dropdownOpen === menu ? null : menu);
  };

  // Close dropdowns if click is outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setDropdownOpen(null);
        setMenuOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  return (
    <nav className="bg-white shadow" ref={menuRef}>
      <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
        {/* Brand */}
        <Link to="/dashboard" className="text-2xl font-bold text-blue-600">
          CampusConnect
        </Link>

        {/* Desktop Menu */}
        <ul className="hidden md:flex gap-6 items-center relative">
          {/* STUDENT */}
          {userRole === "student" && (
            <>
              <li>
                <Link to="/dashboard" className="text-gray-700 hover:text-blue-600">
                  Dashboard
                </Link>
              </li>
              <li className="relative">
                <button
                  onClick={() => toggleDropdown("support")}
                  className="text-gray-700 hover:text-blue-600"
                >
                  Support ▼
                </button>
                {dropdownOpen === "support" && (
                  <ul className="absolute top-full left-0 bg-white shadow-md rounded mt-2 w-40 z-10">
                    <li>
                      <Link to="/support" className="block px-4 py-2 hover:bg-blue-50">
                        Request Support
                      </Link>
                    </li>
                    <li>
                      <Link to="/feedback" className="block px-4 py-2 hover:bg-blue-50">
                        Submit Feedback
                      </Link>
                    </li>
                  </ul>
                )}
              </li>
            </>
          )}

          {/* ADMIN */}
          {userRole === "admin" && (
            <>
              <li>
                <Link to="/admin-dashboard" className="text-gray-700 hover:text-blue-600">
                  Admin Dashboard
                </Link>
              </li>
              <li className="relative">
                <button
                  onClick={() => toggleDropdown("announcements")}
                  className="text-gray-700 hover:text-blue-600"
                >
                  Announcements ▼
                </button>
                {dropdownOpen === "announcements" && (
                  <ul className="absolute top-full left-0 bg-white shadow-md rounded mt-2 w-48 z-10">
                    <li>
                      <Link to="/admin-announcements" className="block px-4 py-2 hover:bg-blue-50">
                        Post Announcements
                      </Link>
                    </li>
                    <li>
                      <Link to="/announcements" className="block px-4 py-2 hover:bg-blue-50">
                        View Announcements
                      </Link>
                    </li>
                  </ul>
                )}
              </li>
              <li className="relative">
                <button
                  onClick={() => toggleDropdown("students")}
                  className="text-gray-700 hover:text-blue-600"
                >
                  Student Profiles ▼
                </button>
                {dropdownOpen === "students" && (
                  <ul className="absolute top-full left-0 bg-white shadow-md rounded mt-2 w-48 z-10">
                    <li>
                      <Link to="/admin-students" className="block px-4 py-2 hover:bg-blue-50">
                        All Students
                      </Link>
                    </li>
                    <li>
                      <Link to="/admin-student-profile" className="block px-4 py-2 hover:bg-blue-50">
                        Individual Profile
                      </Link>
                    </li>
                  </ul>
                )}
              </li>
            </>
          )}

          {/* Logout */}
          <li>
            <button
              onClick={handleLogout}
              className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600"
            >
              Logout
            </button>
          </li>
        </ul>

        {/* Mobile Hamburger */}
        <button
          className="md:hidden text-gray-700 hover:text-blue-600 focus:outline-none"
          onClick={() => setMenuOpen(!menuOpen)}
        >
          {menuOpen ? "✕" : "☰"}
        </button>
      </div>

      {/* Mobile Menu */}
      {menuOpen && (
        <ul className="md:hidden bg-white shadow-md px-6 py-4 space-y-2">
          {/* STUDENT */}
          {userRole === "student" && (
            <>
              <li>
                <Link to="/dashboard" className="block text-gray-700 hover:text-blue-600">
                  Dashboard
                </Link>
              </li>
              <li>
                <button
                  onClick={() => toggleDropdown("support")}
                  className="w-full text-left text-gray-700 hover:text-blue-600"
                >
                  Support ▼
                </button>
                {dropdownOpen === "support" && (
                  <ul className="pl-4 mt-1 space-y-1">
                    <li>
                      <Link to="/support" className="block px-2 py-1 hover:bg-blue-50 rounded">
                        Request Support
                      </Link>
                    </li>
                    <li>
                      <Link to="/feedback" className="block px-2 py-1 hover:bg-blue-50 rounded">
                        Submit Feedback
                      </Link>
                    </li>
                  </ul>
                )}
              </li>
            </>
          )}

          {/* ADMIN */}
          {userRole === "admin" && (
            <>
              <li>
                <Link to="/admin-dashboard" className="block text-gray-700 hover:text-blue-600">
                  Admin Dashboard
                </Link>
              </li>
              <li>
                <button
                  onClick={() => toggleDropdown("announcements")}
                  className="w-full text-left text-gray-700 hover:text-blue-600"
                >
                  Announcements ▼
                </button>
                {dropdownOpen === "announcements" && (
                  <ul className="pl-4 mt-1 space-y-1">
                    <li>
                      <Link to="/admin-announcements" className="block px-2 py-1 hover:bg-blue-50 rounded">
                        Post Announcements
                      </Link>
                    </li>
                    <li>
                      <Link to="/announcements" className="block px-2 py-1 hover:bg-blue-50 rounded">
                        View Announcements
                      </Link>
                    </li>
                  </ul>
                )}
              </li>
              <li>
                <button
                  onClick={() => toggleDropdown("students")}
                  className="w-full text-left text-gray-700 hover:text-blue-600"
                >
                  Student Profiles ▼
                </button>
                {dropdownOpen === "students" && (
                  <ul className="pl-4 mt-1 space-y-1">
                    <li>
                      <Link to="/admin-students" className="block px-2 py-1 hover:bg-blue-50 rounded">
                        All Students
                      </Link>
                    </li>
                    <li>
                      <Link to="/admin-student-profile" className="block px-2 py-1 hover:bg-blue-50 rounded">
                        Individual Profile
                      </Link>
                    </li>
                  </ul>
                )}
              </li>
            </>
          )}

          {/* Logout */}
          <li>
            <button
              onClick={handleLogout}
              className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 w-full"
            >
              Logout
            </button>
